// Removed silently after every AI call, before sanitizeWorkspace: reference/ never reaches the
// compiler, the extracted source, the zip or the live view.
function dropRefs(ws) { rmrf(path.join(ws, "reference")); }

function hasSecret(text) {
  if (/sk-ant-[A-Za-z0-9_-]{10,}/.test(text)) return true;
  return SECRETS.some((s) => s && s.length >= 16 && text.includes(s)) || credentialSecrets().some((s) => text.includes(s));
}
function childEnv(withAi) {
  const env = { PATH: process.env.PATH, HOME: process.env.HOME || "/home/claude", JAVA_HOME: process.env.JAVA_HOME, LANG: "C.UTF-8" };
  if (withAi) {
    for (const k of ["CLAUDE_CODE_OAUTH_TOKEN", "ANTHROPIC_API_KEY", "ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_BASE_URL", "CLAUDE_CONFIG_DIR"]) if (process.env[k]) env[k] = process.env[k];
    env.DISABLE_AUTOUPDATER = "1";
    env.DISABLE_ERROR_REPORTING = "1";
    env.DISABLE_BUG_COMMAND = "1";
    // Live code (0.4+): CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC / DISABLE_TELEMETRY also switch off
    // the CLI's eager tool-input streaming (measured 2026-10-07: Write input then arrives in one burst
    // at the end instead of ~20 deltas/s). Egress stays limited by the container firewall to the
    // Anthropic API hosts either way. MB_LIVE_STREAM=off restores the 0.3 behaviour.
    if (!LIVE_STREAM) env.DISABLE_TELEMETRY = "1";
