let healthCache: { at: number; v: { ok: boolean; [k: string]: unknown } | null } | null = null;
/** /health, cached for 5 minutes (also a failure, for 1 minute): used for the engine release record. */
export async function svcHealthCached(): Promise<{ ok: boolean; [k: string]: unknown } | null> {
  if (healthCache && Date.now() - healthCache.at < (healthCache.v ? 300_000 : 60_000)) return healthCache.v;
  const v = await svcHealth();
  healthCache = { at: Date.now(), v };
  return v;
}

