#!/usr/bin/env node
// Stdio MCP server for one build: answers catalog_search / catalog_get over the pool the portal already gated
// (see catalog.js). No network, no files other than the offer, no dependencies. Line-delimited JSON-RPC 2.0.
//   node catalog-mcp.js <offer.json>
const fs = require("fs");

const offer = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
const STOP = new Set(["a", "an", "the", "and", "or", "of", "for", "to", "in", "on", "with", "at", "by", "from", "my", "your", "some", "any", "that", "this", "is", "it"]);
let calls = 0;

const words = (t) => String(t).toLowerCase().replace(/['’]/g, "").split(/[^a-z0-9]+/).filter((w) => w.length >= 2 && !STOP.has(w));
const out = (o) => process.stdout.write(JSON.stringify(o) + "\n");
const text = (body) => JSON.stringify(body);

function search(input) {
  const query = typeof input.query === "string" ? input.query.trim().slice(0, 120) : "";
  if (query.length < 2) return { ok: false, body: { error: "query must be 2-120 characters" } };
  if (input.kind != null && !offer.pool.some((p) => p.kind === input.kind) && !["model", "texture-set", "texture", "sprite", "hdri", "decal", "sound", "music"].includes(input.kind)) return { ok: false, body: { error: "unknown kind" } };
  const kind = input.kind == null ? null : input.kind;
  const minQuality = Number.isInteger(input.minQuality) ? Math.max(0, Math.min(100, input.minQuality)) : 40;
  const limit = Number.isInteger(input.limit) ? Math.max(1, Math.min(offer.searchLimitMax, input.limit)) : Math.min(6, offer.searchLimitMax);
  const q = words(query);
  const hits = [];
  for (const p of offer.pool) {
    if (kind && p.kind !== kind) continue;
    if (p.q < minQuality) continue;
    const ws = new Set(p.words);
    let n = 0;
    for (const w of q) if (ws.has(w) || (w.length >= 4 && p.words.some((x) => x.startsWith(w) || w.startsWith(x) && x.length >= 4))) n++;
    const share = q.length ? n / q.length : 1;
    if (share < 0.5) continue;
    hits.push({ p, score: share * share * (0.5 + 0.5 * p.rank) });
  }
  hits.sort((a, b) => b.score - a.score || b.p.q - a.p.q || (a.p.id < b.p.id ? -1 : 1));
  const rows = hits.slice(0, limit).map((h) => h.p.row);
  let body = { n: hits.length, game: offer.game, scope: "assets retrieved for this request", rows };
  if (JSON.stringify(body).length > offer.resultCharBudget) body = { ...body, rows: rows.map(({ d: _d, ...x }) => x) };
  while (JSON.stringify(body).length > offer.resultCharBudget && body.rows.length > 1) body = { ...body, rows: body.rows.slice(0, -1) };
  if (!rows.length) body.hint = "no match among the assets retrieved for this request: try other words, another kind or a lower minQuality, or make the asset yourself";
  return { ok: true, body };
}

function get(input) {
  const raw = typeof input.id === "string" ? input.id.toLowerCase() : "";
  const hex = raw.replace(/^(cat:|c:)/, "");
  if (!/^[0-9a-f]{12,64}$/.test(hex)) return { ok: false, body: { error: "not_found" } };
  const m = offer.pool.filter((p) => p.ref.slice(4).startsWith(hex) || p.id.slice(2).startsWith(hex));
  if (m.length !== 1) return { ok: false, body: { error: "not_found" } };
  return { ok: true, raw: m[0].detail };
}

function handle(msg) {
  const { id, method, params } = msg;
  if (method === "initialize") {
    return out({ jsonrpc: "2.0", id, result: { protocolVersion: (params && params.protocolVersion) || "2025-06-18", capabilities: { tools: {} }, serverInfo: { name: "cyrus-catalog", version: offer.v } } });
  }
  if (method === "ping") return out({ jsonrpc: "2.0", id, result: {} });
  if (method === "tools/list") return out({ jsonrpc: "2.0", id, result: { tools: offer.tools.map((t) => ({ name: t.name, description: t.description, inputSchema: t.input_schema })) } });
  if (method === "tools/call") {
    const name = params && params.name;
    const args = (params && params.arguments && typeof params.arguments === "object") ? params.arguments : {};
    calls++;
    let r;
    if (calls > offer.maxCalls) r = { ok: false, body: { error: `catalog call limit (${offer.maxCalls}) reached for this build` } };
    else if (name === "catalog_search") r = search(args);
    else if (name === "catalog_get") r = get(args);
    else r = { ok: false, body: { error: `unknown tool ${name}` } };
    return out({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: r.raw != null ? r.raw : text(r.body) }], isError: !r.ok } });
  }
  if (id !== undefined && id !== null) return out({ jsonrpc: "2.0", id, error: { code: -32601, message: `method not found: ${method}` } });
  // notifications (notifications/initialized, cancelled, ...) need no answer
}

let buf = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (d) => {
  buf += d;
  let i;
  while ((i = buf.indexOf("\n")) >= 0) {
    const line = buf.slice(0, i).trim(); buf = buf.slice(i + 1);
    if (!line) continue;
    let msg; try { msg = JSON.parse(line); } catch { out({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "parse error" } }); continue; }
    try { handle(msg); } catch (e) { if (msg && msg.id != null) out({ jsonrpc: "2.0", id: msg.id, error: { code: -32603, message: String(e && e.message || e).slice(0, 200) } }); }
  }
});
process.stdin.on("end", () => process.exit(0));

