import { readFileSync } from "node:fs";
import path from "node:path";
import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import { ingestRows, type IngestInput } from "../lib/cyrus/library/v2/pipeline";
import type { PackInfo } from "../lib/cyrus/library/v2/stage-a";

const dir = path.join(import.meta.dirname, "fixtures/cyrus-catalog");
export function loadGoldenSample(): { rows: IngestInput[]; packs: Record<string, PackInfo> } {
  const rows = readFileSync(path.join(dir, "staged-sample-200.jsonl"), "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l) as IngestInput);
  const packs = JSON.parse(readFileSync(path.join(dir, "packs.json"), "utf8")) as Record<string, PackInfo>;
  return { rows: rows.map((r) => ({ raw: r.raw, side: r.side ?? undefined })), packs };
}

export async function goldenSummary(s: { rows: IngestInput[]; packs: Record<string, PackInfo> }) {
  const r = await ingestRows(s.rows, { profiles: [minecraftAssetProfile], packs: s.packs, now: "2026-10-10T00:00:00Z" });
  const entries = [...r.entries].sort((a, b) => (a.id < b.id ? -1 : 1)).map((e) => [
    e.id.slice(0, 12), e.kind, e.title, e.categories.primary, e.enrichment.coverage, e.useFor.join(","), e.style ?? "-", e.quality.score, e.games.minecraft?.fit ?? "-", e.status,
  ].join(" | "));
  return { summary: { rows: r.report.rows, coverage: r.report.coverage, status: r.report.status, invalid: r.report.invalid }, entries };
}
