// Catalog tools in builds (CYRUS_CATALOG_TOOLS): the portal pool (real gated catalog_search/catalog_get over the 200-row
// real-catalog sample), the host switch (off = no lookups), the build service's offer parsing / MCP server / pick
// collection, and the real server.js pipeline offline with a fake CLI that talks to the MCP server like Claude Code
// would. Proves: no offer = no MCP flag, no prompt part, no new record fields (byte-identical to before).
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, type ChildProcess } from "node:child_process";
import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import { ingestRows } from "../lib/cyrus/library/v2/pipeline";
import { createMemoryCatalogIndex, type CatalogIndex } from "../lib/cyrus/library/v2/retrieval";
import { access, CATALOG_TOOLS, RESULT_CHAR_BUDGET } from "../lib/cyrus/library/v2/tools";
import { buildCatalogOffer, librarySlotsFromService, offerQueries, OFFER_CHAR_BUDGET, POOL_MAX, type SvcCatalogOffer } from "../lib/cyrus/library/v2/build-offer";
import { catalogOfferForBuild } from "../lib/cyrus/library/v2/build-wiring";
import { ModSpecV1Schema } from "../lib/cyrus/engine-core/spec";
import { loadGoldenSample } from "./_cyrus-catalog-golden";

// eslint-disable-next-line @typescript-eslint/no-require-imports
const CAT = require("../services/modbuilder/catalog.js");
const ROOT = path.resolve(__dirname, "..");
const SVC = path.join(ROOT, "services/modbuilder");
const PROMPT = "Add a brick wall block, a wooden barrel prop and a crosshair icon for the sniper";

let index: CatalogIndex;
let offer: SvcCatalogOffer;
before(async () => {
  const s = loadGoldenSample();
  const r = await ingestRows(s.rows, { profiles: [minecraftAssetProfile], packs: s.packs, now: "2026-10-10T00:00:00Z" });
  index = createMemoryCatalogIndex(r.entries);
  const o = await buildCatalogOffer({ index, plan: "all", game: "minecraft", proprietaryCleared: false, text: PROMPT });
  assert.ok(o, "the top plan gets a pool for this prompt");
  offer = o;
});

describe("portal: the gated pool", () => {
  it("queries are deterministic: word pairs, then words", () => {
    assert.deepEqual(offerQueries("A wooden barrel and a brick wall"), ["wooden barrel", "barrel brick", "brick wall", "wooden", "barrel", "brick", "wall"]);
    assert.deepEqual(offerQueries("a an the"), []);
  });
  it("the pool holds only assets the plan may use, each with its catalog_get answer and ref, within budget", async () => {
    assert.ok(offer.pool.length > 3 && offer.pool.length <= POOL_MAX, `pool ${offer.pool.length}`);
    assert.ok(JSON.stringify(offer).length <= OFFER_CHAR_BUDGET);
    assert.deepEqual(offer.tools.map((t) => t.name), CATALOG_TOOLS.map((t) => t.name));
    assert.equal(offer.resultCharBudget, RESULT_CHAR_BUDGET);
    const a = access("all", false);
    for (const p of offer.pool) {
      assert.match(p.ref, /^cat:[0-9a-f]{64}$/);
      assert.equal(JSON.parse(p.detail).ref, p.ref);
      assert.ok(a.kinds.includes(p.kind));
      const e = await index.get(p.ref.slice(4));
      assert.equal(e?.status, "published");
      assert.ok(a.tiers.includes(e!.licence.tier));
    }
    const words = offer.pool.flatMap((p) => p.words);
    assert.ok(words.includes("brick") || words.includes("bricks"), "brick assets retrieved");
  });
  it("plans that may use nothing get no pool (free, katara, unknown); saka gets sounds only (none in this sample)", async () => {
    for (const plan of ["free", "katara", "nope", null]) assert.equal(await buildCatalogOffer({ index, plan, game: "minecraft", proprietaryCleared: true, text: PROMPT }), null, String(plan));
    assert.equal(await buildCatalogOffer({ index, plan: "saka", game: "minecraft", proprietaryCleared: true, text: PROMPT }), null);
  });
  it("host switch: off = null before ANY lookup; no index / old service = null; on = the pool", async () => {
    let calls = 0;
    const deps = { tierOf: async () => { calls++; return "all"; }, serviceSupports: async () => { calls++; return true; }, index: async () => { calls++; return index; } };
    assert.equal(await catalogOfferForBuild({ userId: "u1", text: PROMPT }, { ...deps, on: () => false }), null);
    assert.equal(calls, 0, "flag off: no plan lookup, no index, no health probe");
    const prev = process.env.CYRUS_CATALOG_TOOLS; delete process.env.CYRUS_CATALOG_TOOLS;
    assert.equal(await catalogOfferForBuild({ userId: "u1", text: PROMPT }, deps), null, "default switch reads CYRUS_CATALOG_TOOLS (unset = off)");
    if (prev !== undefined) process.env.CYRUS_CATALOG_TOOLS = prev;
    assert.equal(calls, 0);
    assert.equal(await catalogOfferForBuild({ userId: "u1", text: PROMPT }, { ...deps, on: () => true, index: async () => null }), null);
    assert.equal(await catalogOfferForBuild({ userId: "u1", text: PROMPT }, { ...deps, on: () => true, serviceSupports: async () => false }), null);
    assert.equal(await catalogOfferForBuild({ userId: "u1", text: PROMPT }, { ...deps, on: () => true, tierOf: async () => { throw new Error("db down"); } }), null, "plan unknown fails closed");
    const o = await catalogOfferForBuild({ userId: "u1", text: PROMPT }, { ...deps, on: () => true });
    assert.equal(o?.pool.length, offer.pool.length);
  });
  it("picks coming back become valid ModSpec asset slots; anything malformed is dropped", () => {
    const ref = offer.pool[0].ref;
    const slots = librarySlotsFromService([
      { id: "brick_wall", kind: "texture", purpose: "the wall block", libraryRef: ref },
      { id: "brick_wall", kind: "texture", purpose: "duplicate", libraryRef: ref },
      { id: "Bad", kind: "texture", purpose: "bad id", libraryRef: ref },
      { id: "x1", kind: "music", purpose: "bad kind", libraryRef: ref },
      { id: "x2", kind: "sound", purpose: "bad ref", libraryRef: "cat:123" },
    ]);
    assert.deepEqual(slots, [{ id: "brick_wall", kind: "texture", purpose: "the wall block", source: "library", libraryRef: ref, requirementIds: [] }]);
    assert.deepEqual(librarySlotsFromService("nope"), []);
    const spec = ModSpecV1Schema.safeParse({ schemaVersion: 1, game: "minecraft", title: "t", summary: "summary text", requirements: [], assets: slots, tests: [] });
    if (!spec.success) assert.ok(!JSON.stringify(spec.error.issues).includes("assets"), JSON.stringify(spec.error.issues));
  });
});

describe("build service: catalog.js + catalog-mcp.js", () => {
  it("parses the offer; absent = null; malformed = an error", () => {
    assert.equal(CAT.parseCatalogOffer(undefined), null);
    const p = CAT.parseCatalogOffer(JSON.parse(JSON.stringify(offer)));
    assert.ok(!p.error, p.error);
    assert.equal(p.pool.length, offer.pool.length);
    for (const bad of ["x", [], { ...offer, v: "v9" }, { ...offer, tools: [offer.tools[0]] }, { ...offer, pool: [] }, { ...offer, pool: [{ ...offer.pool[0], ref: "cat:1" }] }, { ...offer, pool: [offer.pool[0], offer.pool[0]] }]) {
      assert.ok(CAT.parseCatalogOffer(bad)?.error, JSON.stringify(bad).slice(0, 80));
    }
  });
  it("no offer: no CLI args, no prompt part, picks untouched (sanitize removes the file like any other)", () => {
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "cat-ws-"));
    try {
      const rec = { id: "b1" };
      assert.deepEqual(CAT.cliArgs(rec, ws), []);
      assert.equal(CAT.promptSection(rec), "");
      fs.mkdirSync(path.join(ws, "assets"), { recursive: true });
      fs.writeFileSync(path.join(ws, CAT.PICKS_FILE), "{}");
      assert.equal(CAT.collectPicks(ws, rec), null);
      assert.ok(fs.existsSync(path.join(ws, CAT.PICKS_FILE)));
      assert.deepEqual(CAT.publicFacts(rec), {});
    } finally { fs.rmSync(ws, { recursive: true, force: true }); }
  });
  it("the MCP server answers initialize, tools/list (portal definitions), search within budget, get with ref, and caps calls", async () => {
    const work = fs.mkdtempSync(path.join(os.tmpdir(), "cat-mcp-"));
    try {
      const rec = { id: "b2", catalog: CAT.parseCatalogOffer(JSON.parse(JSON.stringify(offer))) };
      const args = CAT.cliArgs(rec, work);
      assert.equal(args[0], "--mcp-config");
      assert.deepEqual(args.slice(2), ["--allowedTools", "mcp__cyrus_catalog__catalog_search", "mcp__cyrus_catalog__catalog_get"]);
      assert.match(CAT.promptSection(rec), /ASSET CATALOG \(this build\)/);
      const cfg = JSON.parse(fs.readFileSync(args[1], "utf8")).mcpServers.cyrus_catalog;
      const replies = await mcpSession(cfg.command, cfg.args, [
        { jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "t", version: "1" } } },
        { jsonrpc: "2.0", method: "notifications/initialized" },
        { jsonrpc: "2.0", id: 2, method: "tools/list" },
        { jsonrpc: "2.0", id: 3, method: "tools/call", params: { name: "catalog_search", arguments: { query: "brick wall" } } },
        { jsonrpc: "2.0", id: 4, method: "tools/call", params: { name: "catalog_get", arguments: { id: offer.pool[0].id } } },
        { jsonrpc: "2.0", id: 5, method: "tools/call", params: { name: "catalog_get", arguments: { id: "c:ffffffffffff" } } },
        ...[6, 7, 8, 9, 10, 11].map((id) => ({ jsonrpc: "2.0", id, method: "tools/call", params: { name: "catalog_search", arguments: { query: "barrel" } } })),
        { jsonrpc: "2.0", id: 12, method: "nope" },
      ]);
      const byId = new Map(replies.map((r) => [r.id, r]));
      assert.equal(byId.get(1).result.protocolVersion, "2025-06-18");
      assert.deepEqual(byId.get(2).result.tools.map((t: { name: string; inputSchema: unknown }) => [t.name, t.inputSchema]), CATALOG_TOOLS.map((t) => [t.name, t.input_schema]));
      const s = byId.get(3).result; const sb = JSON.parse(s.content[0].text);
      assert.equal(s.isError, false);
      assert.ok(sb.rows.length >= 1 && s.content[0].text.length <= RESULT_CHAR_BUDGET, s.content[0].text);
      assert.equal(byId.get(4).result.content[0].text, offer.pool[0].detail);
      assert.equal(byId.get(5).result.isError, true);
      assert.match(byId.get(11).result.content[0].text, /call limit/);
      assert.equal(byId.get(12).error.code, -32601);
      assert.ok(!byId.has(undefined), "notifications get no answer");
      CAT.dropFiles(rec, work);
      assert.ok(!fs.existsSync(path.join(work, "b2-catalog")));
    } finally { fs.rmSync(work, { recursive: true, force: true }); }
  });
  it("collectPicks keeps refs from the pool only, checks kind, removes the file; a round without the file keeps earlier picks", () => {
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "cat-picks-"));
    try {
      const rec: Record<string, unknown> = { id: "b3", catalog: CAT.parseCatalogOffer(JSON.parse(JSON.stringify(offer))) };
      const p0 = offer.pool[0];
      const kind = p0.kind === "model" ? "model" : "texture";
      fs.mkdirSync(path.join(ws, "assets"), { recursive: true });
      fs.writeFileSync(path.join(ws, CAT.PICKS_FILE), JSON.stringify({ slots: [
        { id: "pick_one", kind, purpose: "used for the thing", libraryRef: p0.ref },
        { id: "foreign", kind, purpose: "not offered", libraryRef: "cat:" + "a".repeat(64) },
        { id: "wrong_kind", kind: "sound", purpose: "kind mismatch", libraryRef: p0.ref },
      ] }));
      const slots = CAT.collectPicks(ws, rec);
      assert.deepEqual(slots.map((x: { id: string }) => x.id), ["pick_one"]);
      assert.deepEqual((rec.libraryDropped as { id: string }[]).map((d) => d.id), ["foreign", "wrong_kind"]);
      assert.ok(!fs.existsSync(path.join(ws, CAT.PICKS_FILE)));
      assert.equal(CAT.collectPicks(ws, rec), null);
      assert.equal((rec.librarySlots as unknown[]).length, 1);
      const pub = CAT.publicFacts(rec);
      assert.deepEqual(Object.keys(pub).sort(), ["catalogOffered", "libraryDropped", "librarySlots"]);
      assert.ok(!("pool" in pub.catalogOffered && Array.isArray(pub.catalogOffered.pool)));
    } finally { fs.rmSync(ws, { recursive: true, force: true }); }
  });
});

function mcpSession(cmd: string, args: string[], msgs: object[]): Promise<{ id?: unknown; result?: any; error?: any }[]> { // eslint-disable-line @typescript-eslint/no-explicit-any
  return new Promise((resolve, reject) => {
    const c = spawn(cmd, args, { stdio: ["pipe", "pipe", "pipe"] });
    let out = "", err = "";
    c.stdout.on("data", (d) => { out += d; });
    c.stderr.on("data", (d) => { err += d; });
    c.on("close", () => { try { resolve(out.trim().split("\n").filter(Boolean).map((l) => JSON.parse(l))); } catch (e) { reject(new Error(`${(e as Error).message}: ${out} ${err}`)); } });
    for (const m of msgs) c.stdin.write(JSON.stringify(m) + "\n");
    c.stdin.end();
  });
}

