`;
const YAML_STUB = `module.exports = { parse(t) { const o = {}; for (const l of String(t).split("\\n")) { const m = l.match(/^([\\w.-]+):\\s*(.*)$/); if (m) o[m[1]] = m[2].replace(/^'(.*)'$/, "$1"); } return o; }, stringify(o) { return Object.entries(o).map(([k, v]) => k + ": " + v).join("\\n") + "\\n"; } };`;

describe("server.js pipeline with and without a catalog offer (offline)", () => {
  const KEY = "test-key-0123456789abcdef";
  let dir = "", proc: ChildProcess | null = null, port = 0, svcErr = "";
  const log = () => fs.readFileSync(path.join(dir, "claude.log"), "utf8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
  const api = async (method: string, p: string, body?: unknown) => (await fetch(`http://127.0.0.1:${port}${p}`, { method, headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: body ? JSON.stringify(body) : undefined })).json();
  const waitDone = async (id: string) => {
    for (let i = 0; i < 200; i++) { const r = await api("GET", `/builds/${id}`); if (r.status === "succeeded" || r.status === "failed") return r; await new Promise((res) => setTimeout(res, 100)); }
    throw new Error("build did not finish");
  };
  before(async () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), "mb-cat-"));
