    for (const [n, t] of [["claude", FAKE_CLAUDE], ["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", "#!/usr/bin/env node\n"]]) fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    const cp = path.join(dir, "cp"); fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent.jar\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/plugin/java/JavaPlugin.class\n");
    fs.writeFileSync(path.join(dir, "claude.log"), "");
    const nodePath = path.join(dir, "node_modules");
    let haveYaml = true; try { require.resolve("yaml", { paths: [SVC] }); } catch { haveYaml = false; }
    if (!haveYaml) { fs.mkdirSync(path.join(nodePath, "yaml"), { recursive: true }); fs.writeFileSync(path.join(nodePath, "yaml", "index.js"), YAML_STUB); }
    port = 39000 + Math.floor(Math.random() * 2000);
    proc = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: { PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"), MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_GUARD: "off", MB_ROUTING: "off", NODE_PATH: nodePath } as unknown as NodeJS.ProcessEnv,
      stdio: ["ignore", "ignore", "pipe"],
    });
    proc.stderr?.on("data", (d) => { svcErr += d; });
    for (let i = 0; i < 100; i++) {
      try { const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json(); if (h.ok) return; } catch { /* starting */ }
      await new Promise((res) => setTimeout(res, 100));
    }
    throw new Error(`service did not start: ${svcErr.slice(-2000)}`);
  });
  after(() => { if (proc) proc.kill("SIGKILL"); fs.rmSync(dir, { recursive: true, force: true }); });

  it("/health advertises catalogTools and reports the auth kind", async () => {
    const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json();
    assert.equal(h.features.catalogTools, true);
    assert.equal(h.auth, "none");
  });
  it("no offer: no --mcp-config / --allowedTools, no prompt part, no new record fields", async () => {
    await api("POST", "/builds", { id: "cat-off-01", prompt: "Say hello to every player who joins", mcVersion: "1.21.11" });
    const r = await waitDone("cat-off-01");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events) + svcErr.slice(-2000));
    const c = log().at(-1);
    assert.equal(c.mcp, false); assert.deepEqual(c.allowed, []); assert.equal(c.catalogInSys, false);
    assert.ok(!c.args.includes("--mcp-config") && !c.args.includes("--allowedTools"));
