    assert.match(String(r.error), /^catalog:/);
  });
  it("with an offer: the CLI gets the MCP server, the model's pick comes back as a slot, a foreign ref is dropped, nothing ships", async () => {
    await api("POST", "/builds", { id: "cat-on-01", prompt: PROMPT, mcVersion: "1.21.11", catalog: offer });
