    assert.ok(!("catalog" in r), "the pool never travels back");
    assert.ok(!r.files.some((f: { path: string }) => f.path.startsWith("assets/")), "the picks file is not in the source");
    assert.ok(!r.events.some((e: { message: string }) => /library\.json/.test(e.message)));
    assert.equal(librarySlotsFromService(r.librarySlots).length, 1);
